"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["18414"],{17524(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.geo.importacao.em_andamento","status":409,"titulo":"J\xe1 existe uma importa\xe7\xe3o do Geo em andamento"},"descricao":{"codigo":"uniplus.geo.importacao.em_andamento","requisitos":["UNI-REQ-0530"],"oQueAconteceu":["O Geo faz uma carga da base dos Correios por vez, e j\xe1 existe uma em andamento. O envio do pacote foi recusado com **409**, nenhuma execu\xe7\xe3o foi registrada por causa dele e o arquivo enviado, se chegou a ser recebido, foi apagado.","A recusa acontece em tr\xeas situa\xe7\xf5es. A primeira \xe9 haver outro envio em curso na mesma inst\xe2ncia do Geo, at\xe9 o fim da resposta dele. A segunda \xe9 existir uma carga sendo executada por alguma inst\xe2ncia do Geo. Uma execu\xe7\xe3o registrada como em andamento cujo processo j\xe1 terminou \xe9 encerrada como falha no envio seguinte, e esse envio n\xe3o \xe9 recusado por causa dela. A terceira \xe9 dois envios chegarem juntos: os dois leem o arquivo, s\xf3 um consegue reservar a carga no banco de dados, e o outro \xe9 recusado depois da leitura."],"comoResolver":["Acompanhe a execu\xe7\xe3o em andamento pelo endere\xe7o que a resposta do envio dela devolveu e espere que termine, conclu\xedda ou com falha. Depois, envie o pacote de novo. Repetir o envio enquanto a outra carga n\xe3o termina d\xe1 o mesmo resultado.","Se a execu\xe7\xe3o em andamento n\xe3o terminar e n\xe3o houver outro envio em curso, avise a equipe de suporte do Uni+."],"ondeAparece":["Envio do pacote (`POST /api/admin/geo/importacoes`), quando j\xe1 h\xe1 outro envio em curso ou uma carga em andamento"]},"modulo":{"id":"geo","nome":"Geo","assunto":"Importacao"},"origem":{"repositorio":"unifesspa-edu-br/unifesspa-geo-api","commit":"241f54e88e265e24d3723798ba867fe69845ab0c"}}')}}]);